def compute_mce(probs, outcomes, n_bins=10):
    bins = np.linspace(0, 1, n_bins + 1)
    mce = 0.0
    for i in range(n_bins):
        mask = (probs >= bins[i]) & (probs < bins[i+1])
        if mask.sum() < 3: continue
        mce = max(mce, abs(outcomes[mask].mean() - probs[mask].mean()))
    return float(mce)
